int xfs_attr_add_shortform(xfs_da_args_t *args) {
    int error;

    trace_xfs_attr_add(args->dp, args->name, args->val, args->namelen,
                       args->valuelen, args->flags, _RET_IP_);

    /* Check for replace/create flags and existence */
    if ((args->flags & ATTR_REPLACE) && !xfs_attr_exists(args))
        return -ENOATTR;

    if ((args->flags & ATTR_CREATE) && xfs_attr_exists(args))
        return -EEXIST;

    /* Check name and value size limits */
    if (args->namelen > XFS_ATTR_MAX_NAMELEN || args->valuelen > XFS_ATTR_MAX_VALUELEN)
        return -ENAMETOOLONG;

    /* Calculate new size and check available space */
    if (xfs_attr_size_needed(args) > xfs_attr_space_available(args))
        return -ENOSPC;

    /* If attribute exists, remove it first */
    if (xfs_attr_exists(args)) {
        error = xfs_attr_remove(args);
        if (error)
            return error;
    }

    /* Add the attribute */
    error = xfs_attr_insert(args);
    if (error)
        return error;

    return 0;
}

int xfs_attr_add_short(xfs_da_args_t *args) {
    int error;

    /* Trace the attribute addition operation */
    trace_xfs_attr_add(args);

    /* Check if the attribute already exists */
    error = xfs_attr_lookup(args);
    if (error == 0) {
        /* Attribute exists */
        if (args->op_flags & ATTR_REPLACE)
            return -EEXIST;
        if (args->op_flags & ATTR_CREATE)
            return -EEXIST;

        /* Remove the existing attribute */
        error = xfs_attr_remove(args);
        if (error)
            return error;
    } else if (error != -ENOENT) {
        return error;
    }

    /* Check if the name or value length exceeds the maximum allowed size */
    if (args->name_len > XFS_ATTR_MAXNAMELEN ||
        args->value_len > XFS_ATTR_MAXVALUELEN) {
        return -ENAMETOOLONG;
    }

    /* Calculate the new size required for the attribute */
    args->total_size = args->name_len + args->value_len + XFS_ATTR_HDR_SIZE;

    /* Check if it can fit in the available space */
    if (!xfs_da_space_available(args, args->total_size)) {
        return -ENOSPC;
    }

    /* Add the attribute */
    error = xfs_da_add(args);
    if (error)
        return error;

    return 0;
}

int xfs_attr_add_short(xfs_da_args_t *args) {
    int error;

    trace_xfs_attr_add(args);

    if (args->op_flags & XFS_DA_OP_ADDNAME) {
        error = xfs_da_hasattr(args);
        if (error < 0)
            return error;

        if ((args->op_flags & XFS_DA_OP_REPLACE) && !error)
            return -EEXIST;

        if ((args->op_flags & XFS_DA_OP_CREATE) && error)
            return -ENOENT;

        if (!error) {
            error = xfs_attr_remove(args);
            if (error)
                return error;
        }
    }

    if (args->name_len > XFS_ATTR_MAX_NAME_LEN ||
        args->value_len > XFS_ATTR_MAX_VALUE_LEN)
        return -ENAMETOOLONG;

    error = xfs_da_calculate_size(args);
    if (error < 0)
        return error;

    if (args->total_bytes > args->blksize)
        return -ENOSPC;

    return xfs_da_add(args);
}

int xfs_attr_add_short(xfs_da_args_t *args) {
    int error;

    trace_xfs_attr_add(args->dp, args->name, args->val, args->namelen, args->valuelen, args->flags);

    if ((args->flags & ATTR_REPLACE) && !xfs_attr_exists(args)) {
        return -ENOATTR;
    }

    if ((args->flags & ATTR_CREATE) && xfs_attr_exists(args)) {
        return -EEXIST;
    }

    if (xfs_attr_exists(args)) {
        if ((error = xfs_attr_remove(args)) < 0) {
            return error;
        }
    }

    if (args->namelen > XFS_ATTR_MAXNAMELEN || args->valuelen > XFS_ATTR_MAXVALLEN) {
        return -ENAMETOOLONG;
    }

    int newsize = args->namelen + args->valuelen + sizeof(xfs_attr_leaf_entry_t);
    int available = XFS_ATTR_AVAILABLE_SPACE(args->dp);

    if (newsize > available) {
        return -ENOSPC;
    }

    return xfs_attr_add_leaf(args);
}

int xfs_attr_add_short(xfs_da_args_t *args) {
