        if (args->op_flags & ATTR_REPLACE)
            return -EEXIST;

        if (args->op_flags & ATTR_CREATE)
            return -EEXIST;

        /* Attempt to remove the existing attribute */
        error = xfs_attr_remove(args);
        if (error)
            return error;
    } else if (error != -ENOATTR) {
        return error;
    }

    /* Check if name or value length exceeds maximum allowed size */
    if (args->name_len > XFS_ATTR_MAXNAMELEN || args->value_len > XFS_ATTR_MAXVALLEN)
        return -ENAMETOOLONG;

